mod solution;

fn main() {
    let cases = [
    (r#"[1,2,3,4]"#, r#"24,12,8,6"#),
    (r#"[2,3,4]"#, r#"12,8,6"#),
    (r#"
[2,3,4]
"#, r#"12,8,6"#),
    (r#"  
[1,2,3,4]
  "#, r#"24,12,8,6"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS prefix-suffix-product");
}
